[{"order":1,"type":"heading","text":"Understanding Goroutines and Lifecycle in Go"},{"order":2,"type":"paragraph","text":"Goroutines are lightweight threads managed by the Go runtime. Understanding their lifecycle is crucial for writing concurrent applications that do not leak memory or cause deadlocks."},{"order":3,"type":"subheading","text":"What is a Goroutine?"},{"order":4,"type":"paragraph","text":"A goroutine has a much smaller stack size than traditional operating system threads, starting at just a few kilobytes and growing as needed. You start a goroutine by placing the go keyword before a function call."},{"order":5,"type":"code","text":"package main

import (
	"fmt"
	"time"
)

func sayHello() {
	fmt.Println("Hello from goroutine!")
}

func main() {
	go sayHello()
	time.Sleep(1 * time.Second)
}"},{"order":6,"type":"subheading","text":"The Lifecycle of a Goroutine"},{"order":7,"type":"bullet_point","text":"Creation: Triggered by the go statement, allocating a small stack and placing the goroutine into the scheduler run queue."},{"order":8,"type":"bullet_point","text":"Execution: The Go runtime multiplexes goroutines onto a pool of OS threads using an M:N scheduler."},{"order":9,"type":"bullet_point","text":"Termination: A goroutine naturally terminates when its underlying function returns. If the main function exits, all active goroutines are terminated immediately."},{"order":10,"type":"subheading","text":"Managing Lifecycle with WaitGroups"},{"order":11,"type":"paragraph","text":"Using time.Sleep to wait for goroutines is an anti-pattern. Instead, use the sync.WaitGroup mechanism to properly synchronize and track the lifecycle of multiple goroutines."},{"order":12,"type":"code","text":"package main

import (
	"fmt"
	"sync"
)

func worker(id int, wg *sync.WaitGroup) {
	defer wg.Done()
	fmt.Printf("Worker %d started\n", id)
}

func main() {
	var wg sync.WaitGroup
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go worker(i, &wg)
	}
	wg.Wait()
	fmt.Println("All workers completed.")
}"}]
